luna.Bellen();
Console.WriteLine($"{luna.Name} ist {luna.Alter - bello.Alter} Jahre älter.");

class Hund
{
    public string Name;
    public int Alter;

    public void Bellen()
    {
        Console.WriteLine(Name + " sagt: Wuff!");
    }
}

